import React from "react"
import { Input, Label, UncontrolledTooltip } from "reactstrap"
import imageCompression from "browser-image-compression"
import SuspenseImage from "../../components/SuspenseImage/ImageComponent"

const CardUploader = ({ index, cards, setCards, validation }) => {
  const handleCardChange = async (e, cardIndex) => {
    e.preventDefault()
    if (e.target.files.length) {
      const file = e.target.files[0]
      const options = {
        maxSizeMB: 0.2,
        maxWidthOrHeight: 800,
        useWebWorker: true,
      }

      try {
        const compressedFile = await imageCompression(file, options)

        const newCards = [...cards]
        newCards[cardIndex] = { ...newCards[cardIndex], icon: compressedFile }
        setCards(newCards)
        validation.setFieldValue(`cardImage${cardIndex + 1}`, compressedFile)
      } catch (error) {
        console.error("Image compression failed:", error)
      }
    }
  }

  const getImageSrc = icon => {
    if (icon instanceof Blob) {
      return URL.createObjectURL(icon)
    }
    return icon
  }

  const handleCardTitleChange = (e, cardIndex) => {
    const newCards = [...cards]
    newCards[cardIndex] = { ...newCards[cardIndex], text: e.target.value }
    setCards(newCards)
  }

  const handleCountChange = (e, cardIndex) => {
    const newCards = [...cards]
    newCards[cardIndex] = { ...newCards[cardIndex], count: e.target.value }
    setCards(newCards)
  }

  // Check if the card exists at the given index and has an icon
  const card = cards[index] || {}
  const iconSrc = card.icon ? getImageSrc(card.icon) : null

  return (
    <div>
      <div className="position-relative d-inline-block">
        <div className="position-absolute bottom-0 end-0">
          <Label
            htmlFor={`card${index + 1}-image-input`}
            className="mb-0"
            id={`card${index + 1}ImageInput`}
          >
            <div className="avatar-xs">
              <div className="avatar-title bg-light border rounded-circle text-muted cursor-pointer shadow font-size-16">
                <i className="bx bxs-image-alt"></i>
              </div>
            </div>
          </Label>
          <UncontrolledTooltip
            placement="right"
            target={`card${index + 1}ImageInput`}
          >
            Select Image
          </UncontrolledTooltip>
          <input
            className="form-control d-none"
            id={`card${index + 1}-image-input`}
            type="file"
            accept="image/png, image/gif, image/jpeg"
            onChange={e => handleCardChange(e, index)}
          />
        </div>
        <div className="avatar-lg mt-3">
          <div className="avatar-title bg-light rounded-circle">
            {iconSrc ? (
              <SuspenseImage
                src={iconSrc}
                id={`card${index + 1}-img`}
                alt="Project Logo"
                className="avatar-md rounded-circle overflow-hidden"
                style={{
                  width: "100%",
                  height: "100%",
                  backgroundRepeat: "no-repeat",
                  backgroundPosition: "center",
                  backgroundSize: "cover",
                }}
              />
            ) : null}
          </div>
        </div>
      </div>
      <div className="mb-3">
        <Label htmlFor={`card${index + 1}-count-input`}>Count</Label>
        <Input
          id={`cardCount${index + 1}`}
          name={`cardCount${index + 1}`}
          type="number"
          placeholder={`Enter Count ${index + 1}...`}
          onChange={e => handleCountChange(e, index)}
          value={card.count || ""}
        />
      </div>
      <div className="mb-3">
        <Label htmlFor={`card${index + 1}-title-input`}>Text</Label>
        <Input
          id={`cardTitle${index + 1}`}
          name={`cardTitle${index + 1}`}
          type="text"
          placeholder={`Enter Text ${index + 1}...`}
          onChange={e => handleCardTitleChange(e, index)}
          value={card.text || ""}
        />
      </div>
    </div>
  )
}

export default CardUploader
